import {patchHtml} from '../phone-v2/dom-patch.mjs';
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export async function mountPartTimeJobWindow(container,{service,getContext,isWritable=()=>true,onClose=()=>{}}){
 const doc=container.ownerDocument,root=doc.createElement('section');root.className='part-time-job-window';root.setAttribute('role','dialog');root.setAttribute('aria-modal','true');root.setAttribute('aria-label','打工');container.append(root);
 const style=doc.createElement('style');style.textContent=`.part-time-job-window{position:fixed;left:50%;top:50%;transform:translate(-50%,-50%);width:min(460px,92vw);max-height:90vh;pointer-events:auto;overflow:auto;background:#f5f5f7;color:#1d1d1f;border:1px solid #ffffffb8;border-radius:28px;padding:24px;box-sizing:border-box;box-shadow:0 24px 80px #0005;font:14px/1.5 -apple-system,BlinkMacSystemFont,"PingFang SC",sans-serif}.part-time-job-window *{box-sizing:border-box}.part-time-job-window header{display:flex;gap:12px;align-items:center}.part-time-job-window h2{font-size:23px;letter-spacing:-.6px;margin:0;flex:1}.part-time-job-window header button{border:0;border-radius:50%;width:30px;height:30px;background:#e5e5ea;color:#636366;font-size:20px;cursor:pointer}.part-time-job-window .job-place{color:#86868b;font-size:12px;margin:4px 0 22px}.part-time-job-window .job-description{font-size:14px;color:#636366;margin:0 0 18px}.part-time-job-window .job-options{display:grid;gap:9px}.part-time-job-window .job-choice{display:flex;align-items:center;gap:12px;border:1px solid transparent;border-radius:16px;text-align:left;background:white;padding:14px 15px;color:inherit;font:inherit;cursor:pointer}.part-time-job-window .job-choice[aria-pressed=true]{border-color:#007aff;background:#edf5ff}.part-time-job-window .job-choice:disabled{opacity:.4;cursor:default}.part-time-job-window .job-choice>span{flex:1}.part-time-job-window .job-choice small{display:block;color:#86868b;font-size:11px}.part-time-job-window .job-pay{font-weight:600;font-size:17px}.part-time-job-window .job-pay small{font-weight:400;text-align:right}.part-time-job-window .job-submit{width:100%;border:0;border-radius:13px;background:#007aff;color:white;font:600 15px inherit;min-height:44px;margin:20px 0 0;cursor:pointer}.part-time-job-window .job-submit:disabled{opacity:.35;cursor:default}.part-time-job-window .job-notice{color:#86868b;font-size:12px;margin:10px 0 0;min-height:18px}.part-time-job-window .job-notice[data-error=true]{color:#d92a3b}.part-time-job-window .job-pending{border-top:1px solid #d1d1d6;padding-top:16px;margin-top:20px}.part-time-job-window .job-pending h3{font-size:13px;margin:0 0 10px;color:#86868b;font-weight:500}.part-time-job-window .job-reservation{display:flex;align-items:center;gap:10px;background:white;border-radius:12px;padding:12px;margin-bottom:6px}.part-time-job-window .job-reservation span{flex:1}.part-time-job-window .job-reservation small{display:block;color:#86868b;font-size:11px}.part-time-job-window .job-reservation button{border:0;background:#f0f0f5;color:#007aff;font:inherit;font-size:12px;border-radius:8px;padding:5px 10px;cursor:pointer}@media(max-height:520px){.part-time-job-window{width:min(550px,88vw);padding:18px 22px;max-height:92vh}.part-time-job-window .job-place{margin-bottom:12px}.part-time-job-window .job-description{margin-bottom:10px}.part-time-job-window .job-options{grid-template-columns:repeat(3,1fr);gap:7px}.part-time-job-window .job-choice{display:block;padding:12px 10px}.part-time-job-window .job-pay{margin-top:8px}.part-time-job-window .job-pay small{text-align:left}.part-time-job-window .job-submit{margin-top:12px}.part-time-job-window .job-pending{margin-top:12px;padding-top:12px}}`;root.append(style);const body=doc.createElement('div');root.append(body);
 let choices=[],pending=[],selected=1,busy=false,notice='',error=false,destroyed=false;
 async function refresh(){choices=await service.menu();const snapshot=await service.snapshot(),context=getContext();pending=Object.values(snapshot.jobs??{}).filter(row=>row.status==='staged'&&row.location.id===context.location?.id&&row.date===context.date);render();}
 function render(){if(destroyed)return;const context=getContext(),chosen=choices.find(row=>row.cells===selected),writable=isWritable();patchHtml(body,`<header><h2>${esc(choices[0]?.title??'打工')}</h2><button data-job-close aria-label="关闭打工">×</button></header><p class="job-place">${esc(context.location?.name??'当前位置')}</p><p class="job-description">${esc(choices[0]?.description??'此地点暂时没有工作。')}</p><div class="job-options">${choices.map(choice=>`<button class="job-choice" data-job-cells="${choice.cells}" aria-pressed="${selected===choice.cells}" ${busy||!choice.available||!writable?'disabled':''}><span><strong>${choice.cells} 格 · ${choice.hours} 小时</strong><small>${esc(choice.time||choice.reason)}</small></span><div class="job-pay">¥${choice.money.toLocaleString()}<small>${choice.suspicion?'可疑度 +'+choice.suspicion:'可疑度不变'}</small></div></button>`).join('')}</div><button class="job-submit" data-job-submit ${busy||!writable||!chosen?.available?'disabled':''}>${busy?'正在保存…':'加入日程'}</button><p class="job-notice" data-error="${error}" role="status">${esc(notice||'预约不发钱，完整送出工作日程后领取报酬。')}</p>${pending.length?`<section class="job-pending"><h3>已预约</h3>${pending.map(row=>`<div class="job-reservation"><span>${esc(choices[0]?.title??'打工')}<small>${row.cells} 格 · ¥${row.money.toLocaleString()}${row.suspicion?' · 可疑度 +'+row.suspicion:''}</small></span><button data-job-cancel="${esc(row.nonce)}" ${busy||!writable?'disabled':''}>取消</button></div>`).join('')}</section>`:''}`);}
 async function click(event){const button=event.target.closest('button');if(!button||button.disabled)return;if(button.hasAttribute('data-job-close')){onClose();return;}if(button.hasAttribute('data-job-cells')){selected=Number(button.dataset.jobCells);notice='';error=false;render();return;}busy=true;error=false;notice='';render();try{if(button.hasAttribute('data-job-submit')){const choice=choices.find(row=>row.cells===selected);await service.stage(choice.jobId,selected);notice='已加入日程。';}else if(button.hasAttribute('data-job-cancel')){await service.cancel(button.dataset.jobCancel);notice='预约已取消。';}}catch(reason){notice=reason.message;error=true;}finally{busy=false;await refresh();}}
 const key=event=>{if(event.key==='Escape'){event.stopPropagation();onClose();}};root.addEventListener('click',click);root.addEventListener('keydown',key);await refresh();return{root,refresh,destroy(){destroyed=true;root.removeEventListener('click',click);root.removeEventListener('keydown',key);root.remove();}};
}
